def continuous_summary(self, coverage, close_errors):
    arguments = dict(original_coverage=coverage,
        complete_cell_ledger=self.members.get("complete_cell_ledger"),
        original_error=self.error,original_stop=self.stop,close_errors=close_errors)
    combined = analytic = saved = None
    if self.continuous_defect is not None:
        try:
            # This is the ONLY R580/R596 scientific finish on the bound path.
            # R601 returns both complete originals and owns stopped recovery.
            combined = self.continuous_defect.summary(**arguments)
        except (ResourceStop,MemoryError):
            raise
        except Exception as error:
            self.added_unpaid("continuous","original_owned_finish",error)
        if combined is not None:
            analytic = combined["actual_R580_summary"]
            saved = combined["actual_R596_summary"]
        else:
            # Do not retry an ordinary partially returned finish. Preserve
            # the actually returned prefix and the exact unfinished address.
            analytic = copy.deepcopy(self.continuous_defect.analytic_summary)
            saved = copy.deepcopy(self.continuous_defect.saved_summary)
    else:
        # Binding was unpaid before any R601 finish. Independent original
        # diagnostics may still return; no combined bound is inferred.
        if self.analytic_projection is not None:
            try:
                analytic = self.analytic_projection.summary(**arguments)
            except (ResourceStop,MemoryError):
                raise
            except Exception as error:
                self.added_unpaid("analytic","independent_unbound_finish",error)
        if self.saved_rhs_defect is not None:
            try:
                saved = self.saved_rhs_defect.summary(**arguments)
            except (ResourceStop,MemoryError):
                raise
            except Exception as error:
                self.saved_rhs_unpaid("independent_unbound_finish",error)
    wrapper = self.added_frame("continuous",combined)
    wrapper["actual_unfinished_operation"] = (None if self.continuous_defect is None else
        copy.deepcopy(self.continuous_defect.pending))
    wrapper["actual_original_finish_started"] = (False if self.continuous_defect is None else
        self.continuous_defect.finish_started)
    wrapper["actual_original_summary_call_count"] = (0 if self.continuous_defect is None else
        self.continuous_defect.summary_calls)
    wrapper["actual_R575_context_same_object"] = self.continuous_defect is not None
    wrapper["separate_R596_optional_R575_composition_not_repeated"] = True
    return (self.added_frame("analytic",analytic),
        self.saved_rhs_summary(coverage,close_errors,None,original=saved,already_owned=True),
        wrapper)

